sition:sticky;top:0;background:#f9fafb;padding:11px;text-align:left;text-transform:uppercase;font-size:10px;color:#667085;border-bottom:2px solid #e4e7ec}td{padding:11px;border-bottom:1px solid #eaecf0;vertical-align:top}.num{text-align:right;font-variant-numeric:tabular-nums;font-weight:700}.badge{display:inline-block;padding:4px 8px;border-radius:999px;font-size:10px;font-weight:900;text-transform:uppercase;background:#f2f4f7}.actions{display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap}.deleted{opacity:.58;text-decoration:line-through}.modal-bg{position:fixed;inset:0;background:rgba(15,23,42,.65);display:none;align-items:center;justify-content:center;padding:18px;z-index:9999}.modal-bg.open{display:flex}.modal{width:min(580px,100%);background:#fff;border-radius:15px;overflow:hidden}.modal-head{padding:16px 19px;border-bottom:1px solid #e4e7ec;font-weight:900}.modal-body{padding:19px}.modal-actions{padding:14px 19px;background:#f9fafb;border-top:1px solid #e4e7ec;display:flex;gap:9px;justify-content:flex-end}@media(max-width:900px){.page{padding:20px 14px}.grid,.grid.payment,.filters{grid-template-columns:1fr}.btn{width:100%}}
