<div class="notice info"><strong>Protected workflow:</strong> a bill may be edited only while nothing has been collected against it. Editing voids the original journal voucher and posts a replacement for the corrected amount &mdash; the voided voucher stays visible in the Journal Entry register but is left out of every total. Once an official receipt exists, use a reversal, refund, debit, or credit instead.</div>
<div class="card"><div class="body"><h2 style="font-size:17px;margin:0 0 12px">Reverse or Refund a Payment</h2><form class="grid payment" method="post" action="../process/paymentAdjustmentProcess.php"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><div class="field"><label>Official Receipt Number</label><input name="receipt_no" required placeholder="COL-..."></div><div class="field"><label>Action</label><select name="action"><option value="payment_reversal">Reversal</option><option value="payment_refund">Refund</option></select></div><div class="field"><label>Business Date</label><input type="date" name="business_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><?= render_water_class_field(null, true, 'payClassId') ?></div><div class="field"><label>Reason</label><input name="reason" minlength="5" required placeholder="Explain why the payment must be reversed or refunded"></div><div style="align-self:end"><button class="btn danger" type="submit" data-confirm="This will restore all receivable balances and create a reversing journal. Continue?">Process</button></div></form></div></div>
<div class="card"><div class="body"><form class="filters" method="get"><div class="field"><label>Bill Type</label><select name="type"><?php foreach($labels as $k=>$v):?><option value="<?=e($k)?>" <?=$type===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>Search Member / Account</label><input name="search" value="<?=e($search)?>" placeholder="Name, account, member ID" data-live-search></div><div class="field"><label>Records</label><select name="show_deleted"><option value="0">Active only</option><option value="1" <?=$showDeleted?'selected':''?>>Include deleted</option></select></div><div style="display:flex;gap:8px"><button class="btn" type="submit">Apply</button><a class="btn light" href="billing_adjustments.php">Reset</a></div></form></div></div>
<div class="card"><div class="table-wrap" id="adjRecords" data-live-results><table><thead><tr><th>Type / ID</th><th>Reference</th><th>Member</th><th>Description</th><th>Bill Date</th><th>Due</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php if(!$records):?><tr><td colspan="11" style="text-align:center;padding:30px;color:#667085">No bill records found.</td></tr><?php endif;?>
<?php foreach($records as $r):$deleted=bl_is_deleted($r);$paid=(float)($r['amount_paid']??0);$bt=(string)$r['bill_type'];$editable=bl_row_looks_editable($r,$collectedMap);$label=$r['source_name'].' #'.$r['bill_id'].' — '.$r['member_name'];$editPayload=['bill_type'=>$bt,'bill_id'=>(int)$r['bill_id'],'label'=>$label,'is_inventory'=>strcasecmp(trim((string)($r['bill_code_type']??'')),'Inventory')===0,'is_posted'=>(int)($r['is_billed']??0)===1,'prev_reading'=>$r['prev_reading'],'pres_reading'=>$r['pres_reading'],'consumption'=>$r['consumption'],'quantity'=>$r['quantity'],'total_amount'=>(float)$r['total_amount'],'due_date'=>$r['due_date']];?><tr class="<?=$deleted?'deleted':''?>"><td><strong><?=e($r['source_name'])?></strong><div>#<?=e($r['bill_id'])?></div></td><td><?=e($r['reference_label'])?></td><td><strong><?=e($r['member_name'])?></strong><div>Acct: <?=e($r['account_number']?:$r['member_id'])?></div></td><td><?=e($r['description'])?><?php if((int)($r['bill_edit_count']??0)>0):?><div style="font-size:11px;color:#b54708;font-weight:700">Edited <?=e((int)$r['bill_edit_count'])?>&times;</div><?php endif;?></td><td><?=e(bl_date($r['bill_date']))?></td><td><?=e(bl_date($r['due_date']))?></td><td class="num"><?=e(bl_money($r['total_amount']))?></td><td class="num"><?=e(bl_money($paid))?></td><td class="num"><?=e(bl_money($r['balance']))?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><div class="actions"><?php if(!$deleted):?><?php if($editable):?><button type="button" class="btn edit" onclick='openEdit(<?=json_encode($editPayload,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>)'>Edit</button><?php else:?><span class="locked" title="Editing is locked once a collection exists">Collected &mdash; locked</span><?php endif;?><button type="button" class="btn debit" onclick='openAdjust(<?=json_encode($bt)?>,<?=json_encode((int)$r['bill_id'])?>,<?=json_encode($label)?>,"bill_debit")'>Debit</button><button type="button" class="btn credit" onclick='openAdjust(<?=json_encode($bt)?>,<?=json_encode((int)$r['bill_id'])?>,<?=json_encode($label)?>,"bill_credit")'>Credit</button><?php if($paid<=0 && $bt!=='water'):?><button type="button" class="btn danger" onclick='openDelete(<?=json_encode($bt)?>,<?=json_encode((int)$r['bill_id'])?>)'>Delete</button><?php endif;?><?php else:?>Deleted <?=e(bl_date($r['deleted_at']??null))?><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
</main></div>
<div class="modal-bg" id="adjustModal"><div class="modal"><div class="modal-head">Controlled Bill Adjustment</div><form method="post" action="../process/paymentAdjustmentProcess.php"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" id="adjAction"><input type="hidden" name="bill_type" id="adjType"><input type="hidden" name="bill_id" id="adjId"><div class="modal-body"><p id="adjTitle" style="margin:0 0 14px;color:#475467"></p><div class="grid"><div class="field"><label>Adjustment Amount</label><input type="number" min="0.01" step="0.01" name="amount" required></div><div class="field"><label>Business Date</label><input type="date" name="business_date" value="<?=date('Y-m-d')?>" required></div><div class="field" style="grid-column:1/-1"><?= render_water_class_field(null, true, 'adjClassId') ?></div><div class="field" style="grid-column:1/-1"><label>Reason</label><textarea name="reason" minlength="5" required></textarea></div></div></div><div class="modal-actions"><button type="button" class="btn light" onclick="closeModal('adjustModal')">Cancel</button><button class="btn" type="submit">Post Adjustment</button></div></form></div></div>
<div class="modal-bg" id="deleteModal"><div class="modal"><div class="modal-head">Delete Unused Bill</div><form method="post" action="../process/billLifecycleProcess.php"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="bill_type" id="delType"><input type="hidden" name="bill_id" id="delId"><div class="modal-body"><div class="notice error">Only bills with no payment allocation may be deleted. Paid bills require reversal or refund first.</div><div class="field"><label>Delete Reason</label><textarea name="delete_reason" minlength="5" required></textarea></div></div><div class="modal-actions"><button type="button" class="btn light" onclick="closeModal('deleteModal')">Cancel</button><button class="btn danger" type="submit">Mark Deleted</button></div></form></div></div>
<div class="modal-bg" id="editModal"><div class="modal"><div class="modal-head">Edit Uncollected Bill</div><form method="post" action="../process/billLifecycleProcess.php"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="bill_type" id="editType"><input type="hidden" name="bill_id" id="editId"><div class="modal-body"><p id="editTitle" style="margin:0 0 12px;color:#475467"></p><div class="notice info" style="margin-bottom:14px" id="editJournalNote">Saving voids this bill's journal entry and posts a separate correction entry for the corrected amount, numbered after the invoice (1024-R1, then -R2). The voided entry stays on file but is excluded from every total.</div><div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="field" id="editReadingField" style="display:none"><label>New Present Reading (m&sup3;)</label><input type="number" step="1" min="0" name="pres_reading" id="editPresReading"><div id="editReadingHint" style="font-size:11px;color:#667085;margin-top:6px"></div></div><div class="field" id="editAmountField"><label>New Total Amount</label><input type="number" step="0.01" min="0.01" name="total_amount" id="editTotalAmount"></div><div class="field" id="editQuantityField" style="display:none"><label>New Quantity</label><input type="number" step="0.01" min="0.01" name="quantity" id="editQuantity"><div style="font-size:11px;color:#667085;margin-top:6px">Inventory bills are priced from the bill code, so correct the quantity instead of the amount.</div></div><div class="field" id="editDueField"><label>New Due Date <span style="font-weight:400;text-transform:none">(leave blank to keep)</span></label><input type="date" name="due_date" id="editDueDate"></div><div class="field" style="grid-column:1/-1"><?= render_water_class_field(null, true, 'editClassId', 'class_id', 'form-control', 'Class of the correction') ?></div><div class="field" style="grid-column:1/-1"><label>Reason</label><textarea name="reason" minlength="5" required placeholder="Explain what was wrong with the original bill"></textarea></div></div></div><div class="modal-actions"><button type="button" class="btn light" onclick="closeModal('editModal')">Cancel</button><button class="btn edit" type="submit" data-confirm="The current journal voucher will be voided and replaced. Continue?">Save Correction</button></div></form></div></div>
<script>function openAdjust(t,id,title,a){adjType.value=t;adjId.value=id;adjAction.value=a;adjTitle.textContent=(a==='bill_credit'?'Credit: ':'Debit: ')+title;adjustModal.classList.add('open')}function openDelete(t,id){delType.value=t;delId.value=id;deleteModal.classList.add('open')}
function openEdit(b){editType.value=b.bill_type;editId.value=b.bill_id;editTitle.textContent='Correcting '+b.label;
var water=b.bill_type==='water',inv=!!b.is_inventory&&!water;
editReadingField.style.display=water?'':'none';editAmountField.style.display=(water||inv)?'none':'';editQuantityField.style.display=inv?'':'none';editDueField.style.display=(water||b.bill_type==='installment')?'none':'';
editPresReading.disabled=!water;editTotalAmount.disabled=water||inv;editQuantity.disabled=!inv;editDueDate.disabled=water||b.bill_type==='installment';
editPresReading.value=water?(b.pres_reading!==null?b.pres_reading:''):'';editPresReading.min=water&&b.prev_reading!==null?b.prev_reading:0;
editReadingHint.textContent=water?('Previous reading '+(b.prev_reading!==null?b.prev_reading:0)+' m³, currently '+(b.consumption!==null?b.consumption:0)+' m³ consumed. The amount is recalculated from the current tariff and discount setup.'):'';
editJournalNote.textContent=b.is_posted?'Saving voids this bill\'s journal entry and posts a separate correction entry for the corrected amount, numbered after the invoice (1024-R1, then -R2). The voided entry stays on file but is excluded from every total.':'This bill is not posted yet, so it has no journal entry. Nothing is voided and nothing is posted to the ledger — only the reading and its recalculated amount change.';
editTotalAmount.value=(water||inv)?'':Number(b.total_amount||0).toFixed(2);editQuantity.value=inv?Number(b.quantity||1).toFixed(2):'';editDueDate.value='';
editModal.classList.add('open')}
function closeModal(id){document.getElementById(id).classList.remove('open')}addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal('adjustModal');closeModal('deleteModal');closeModal('editModal')}})</script></body></html>
